910	Status CollectionImpl::optimize(const OptimizeOptions &options) {
911	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
912	
913	  // Serialize against other maintenance operations for the whole optimize.
914	  std::lock_guard maintenance_lock(maintenance_mtx_);
915	
916	  std::vector<Segment::Ptr> persist_segments;
917	
918	  // Phase 1: exclusively seal the current writing segment and snapshot
919	  // the persisted segment set.
920	  {
921	    std::unique_lock schema_lock(schema_handle_mtx_);
922	    // Nothing has been built yet, so failing fast leaves nothing to clean.
923	    CHECK_RETURN_STATUS(check_no_active_iterators("optimize"));
924	    std::lock_guard write_lock(write_mtx_);
925	
926	    CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
927	    CHECK_CLOSED_RETURN_STATUS(closed_, false);
928	
929	    if (writing_segment_->has_record()) {
930	      auto s = switch_to_new_segment_for_writing();
931	      if (!s.ok()) {
932	        return s;
933	      }
934	    }
935	
936	    persist_segments =
937	        get_all_persist_segments();  // will not return writing segment
938	  }
939	
940	  if (persist_segments.size() == 0) {
941	    return Status::OK();
942	  }
943	
944	  // Phase 2: lock-free compact. Readers and writers proceed freely.
945	  auto delete_store_clone = delete_store_->clone();
946	  auto tasks =
947	      build_compact_task(schema_, persist_segments, options.concurrency_,
948	                         delete_store_clone->make_filter());
949	
950	  // execute segment compact task
951	  auto s = execute_compact_task(tasks);
952	  CHECK_RETURN_STATUS(s);
953	
954	  // End of phase 2 (still lock-free): move built tmp segments to their
955	  // final paths and open them before the manifest is persisted, so a
956	  // failure aborts cleanly without a version/disk mismatch.
957	  std::vector<Segment::Ptr> opened_segments;
958	  std::vector<std::string> moved_dirs;
959	  auto cleanup_moved_dirs = [&]() {
960	    for (auto &dir : moved_dirs) {
961	      FileHelper::RemoveDirectory(dir);
962	    }
963	  };
964	  for (auto &task : tasks) {
965	    auto task_info = task->task_info();
966	    if (!std::holds_alternative<CompactTask>(task_info)) {
967	      continue;
968	    }
969	    auto compact_task = std::get<CompactTask>(task_info);
970	    if (!compact_task.output_segment_meta_) {
971	      continue;
972	    }
973	
974	    auto tmp_segment_path =
975	        FileHelper::MakeTempSegmentPath(path_, compact_task.output_segment_id_);
976	    auto new_segment_id = allocate_segment_id();
977	    auto new_segment_path = FileHelper::MakeSegmentPath(path_, new_segment_id);
978	
979	    if (!FileHelper::MoveDirectory(tmp_segment_path, new_segment_path)) {
980	      cleanup_moved_dirs();
981	      return Status::InternalError("move segment directory failed");
982	    }
983	    moved_dirs.push_back(new_segment_path);
984	    compact_task.output_segment_meta_->set_id(new_segment_id);
985	
986	    auto new_segment =
987	        Segment::Open(path_, *schema_, *compact_task.output_segment_meta_,
988	                      id_map_, delete_store_, version_manager_,
989	                      SegmentOptions{true, options_.enable_mmap_});
990	    if (!new_segment.has_value()) {
991	      // best-effort cleanup: these directories are not referenced by any
992	      // manifest yet, so remove them rather than leaking them on disk
993	      cleanup_moved_dirs();
994	      return new_segment.error();
995	    }
996	    opened_segments.push_back(new_segment.value());
997	  }
998	
999	  // Phase 3: short exclusive commit. No readers can be using the old
1000	  // indexers — they all hold the shared schema lock — so in-place
1001	  // reload_vector_index() is safe.
1002	  {
1003	    // No iterator wait: phase 1 rejects open iterators and create_iterator
1004	    // is rejected while optimize holds maintenance_mtx_, so the count is
1005	    // zero here.
1006	    std::unique_lock schema_lock(schema_handle_mtx_);
1007	    std::lock_guard write_lock(write_mtx_);
1008	
1009	    Version new_version = version_manager_->get_current_version();
1010	
1011	    for (auto &task : tasks) {
1012	      auto task_info = task->task_info();
1013	
1014	      if (std::holds_alternative<CompactTask>(task_info)) {
1015	        auto compact_task = std::get<CompactTask>(task_info);
1016	
1017	        if (compact_task.output_segment_meta_) {
1018	          s = new_version.add_persisted_segment_meta(
1019	              compact_task.output_segment_meta_);
1020	          CHECK_RETURN_STATUS(s);
1021	          new_version.set_next_segment_id(segment_id_allocator_.load());
1022	        }
1023	
1024	        for (auto input_segment : compact_task.input_segments_) {
1025	          s = new_version.remove_persisted_segment_meta(input_segment->id());
1026	          CHECK_RETURN_STATUS(s);
1027	        }
1028	      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
1029	        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
1030	        s = new_version.update_persisted_segment_meta(
1031	            create_index_task.output_segment_meta_);
1032	        CHECK_RETURN_STATUS(s);
1033	      }
1034	    }
1035	
1036	    s = version_manager_->apply(new_version);
1037	    CHECK_RETURN_STATUS(s);
1038	
1039	    s = version_manager_->flush();
1040	    CHECK_RETURN_STATUS(s);
1041	
1042	    // publish new segments, retire compacted inputs and reload rebuilt
1043	    // vector indexes
1044	    size_t opened_index = 0;
1045	    for (auto &task : tasks) {
1046	      auto task_info = task->task_info();
1047	
1048	      if (std::holds_alternative<CompactTask>(task_info)) {
1049	        auto compact_task = std::get<CompactTask>(task_info);
1050	
1051	        if (compact_task.output_segment_meta_) {
1052	          if (opened_index >= opened_segments.size()) {
1053	            return Status::InternalError("opened_segments index out of bounds");
1054	          }
1055	          s = segment_manager_->add_segment(opened_segments[opened_index++]);
1056	          CHECK_RETURN_STATUS(s);
1057	        }
1058	
1059	        for (auto input_segment : compact_task.input_segments_) {
1060	          s = segment_manager_->destroy_segment(input_segment->id());
1061	          CHECK_RETURN_STATUS(s);
1062	        }
1063	      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
1064	        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
1065	
1066	        s = create_index_task.input_segment_->reload_vector_index(
1067	            *schema_, create_index_task.output_segment_meta_,
1068	            create_index_task.output_vector_indexers_,
1069	            create_index_task.output_quant_vector_indexers_);
1070	        CHECK_RETURN_STATUS(s);
1071	      }
1072	    }
1073	  }
1074	
1075	  // segment_manager_->destroy_segment() / Segment::destroy() closes the retired
1076	  // segments while the task still hold the shared_ptr of them. Clear to drop
1077	  // the compaction snapshots after releasing the write_mtx so the segment
1078	  // destructors perform recursive directory cleanup without blocking readers
1079	  // and writers.
1080	  tasks.clear();
1081	  persist_segments.clear();
1082	
1083	  return Status::OK();
1084	}
