478	Status SegmentImpl::Open(const SegmentOptions &options) {
479	  options_ = options;
480	  options_.enable_mmap_ = version_manager_->get_current_version().enable_mmap();
481	
482	  filter_ =
483	      std::make_shared<SegmentIndexFilter>(delete_store_, shared_from_this());
484	
485	  // load persist forward blocks
486	  auto s = load_persist_scalar_blocks();
487	  CHECK_RETURN_STATUS(s);
488	
489	  // load scalar indexes
490	  s = load_scalar_index_blocks();
491	  CHECK_RETURN_STATUS(s);
492	
493	  // load FTS indexes
494	  s = open_fts_indexers(false);
495	  CHECK_RETURN_STATUS(s);
496	
497	  // load vector indexes
498	  s = load_vector_index_blocks();
499	  CHECK_RETURN_STATUS(s);
500	
501	  auto writing_block = segment_meta_->writing_forward_block();
502	  if (!writing_block.has_value() && !options_.read_only_) {
503	    return Status::InternalError(
504	        "No writing block found when in writing mode.");
505	  }
506	
507	  if (writing_block.has_value()) {
508	    // init doc_id_allocator and block_id_allocator
509	    doc_id_allocator_ = writing_block.value().min_doc_id();
510	    BlockID max_block_id{writing_block.value().id()};
511	    for (auto &block : segment_meta_->persisted_blocks()) {
512	      max_block_id = std::max(max_block_id, block.id());
513	    }
514	    block_id_allocator_ = max_block_id + 1;
515	
516	    // recover writing block
517	    s = recover();
518	    CHECK_RETURN_STATUS(s);
519	  } else {
520	    // Update block_id_allocator_
521	    BlockID max_block_id{0};
522	    auto &persist_blocks = segment_meta_->persisted_blocks();
523	    for (const auto &block : persist_blocks) {
524	      max_block_id = std::max(max_block_id, block.id());
525	    }
526	    block_id_allocator_.store(max_block_id + 1);
527	  }
528	
529	  fresh_persist_block_offset();
530	
531	  fresh_persist_chunked_array();
532	
533	  return Status::OK();
534	}
