58	int MixedStreamerReducer::set_target_streamer_wiht_info(
59	    const IndexBuilder::Pointer builder, const IndexStreamer::Pointer streamer,
60	    const IndexConverter::Pointer converter,
61	    const IndexReformer::Pointer reformer,
62	    const IndexQueryMeta &original_query_meta) {
63	  if (state_ != STATE_INITED) {
64	    LOG_ERROR("Set target streamer after init");
65	    return IndexError_Uninitialized;
66	  }
67	
68	  target_builder_ = builder;
69	  target_streamer_ = streamer;
70	  target_builder_converter_ = converter;
71	  target_streamer_reformer_ = reformer;
72	  original_query_meta_ = original_query_meta;
73	
74	  is_sparse_ =
