81	int MixedStreamerReducer::feed_streamer_with_reformer(
82	    IndexStreamer::Pointer streamer, const IndexReformer::Pointer reformer) {
83	  if (!(state_ == STATE_STREAMER_SET || state_ == STATE_FEED)) {
84	    LOG_ERROR("Set target streamer or feed before feed");
85	    return IndexError_Uninitialized;
86	  }
87	
88	  if (!streamer) {
89	    LOG_ERROR("Streamer nullptr");
90	    return IndexError_InvalidArgument;
91	  }
92	
93	  auto check_datatype = [&](const IndexMeta & /*target_meta*/,
94	                            const IndexMeta &source_meta) -> bool {
95	    if (!streamers_.empty()) {
96	      auto &last_meta = streamers_.back()->meta();
97	      return last_meta.data_type() == source_meta.data_type() &&
98	             last_meta.dimension() == source_meta.dimension() &&
99	             last_meta.unit_size() == source_meta.unit_size();
100	    }
101	    // TODO: check target meta
102	    return true;
103	  };
104	
105	  auto check_other = [&](const IndexMeta &target_meta,
106	                         const IndexMeta &source_meta) -> bool {
107	    return target_meta.meta_type() == source_meta.meta_type();
108	    // when create a new index, there is a case that ip_flat merged into l2_hnsw
109	    // target_meta.metric_name() == source_meta.metric_name();
110	  };
111	
112	  if (!(check_datatype(target_streamer_->meta(), streamer->meta()) &&
113	        check_other(target_streamer_->meta(), streamer->meta()))) {
114	    LOG_ERROR("Streamer meta mismatch");
115	    return IndexError_InvalidArgument;
116	  }
117	
118	  if (streamers_.empty()) {
119	    is_target_and_source_same_reformer_ =
120	        target_streamer_->meta().reformer_name() ==
121	        streamer->meta().reformer_name();
122	  }
123	
124	  streamers_.push_back(streamer);
125	  source_streamers_reformers_.push_back(reformer);
126	
127	  state_ = STATE_FEED;
128	  return 0;
129	}
