328	void MixedStreamerReducer::add_vec(int *result) {
329	  if (target_builder_ != nullptr) {
330	    add_vec_with_builder(result);
331	    return;
332	  }
333	  ailego::ElapsedTime timer;
334	  auto target_streamer_context = target_streamer_->create_context();
335	  auto target_streamer_query_meta = IndexQueryMeta{
336	      IndexMeta::MetaType::MT_DENSE, target_streamer_->meta().data_type(),
337	      target_streamer_->meta().dimension()};
338	  const bool need_convert = (!is_target_and_source_same_reformer_) &&
339	                            target_streamer_reformer_ != nullptr;
340	
341	  AILEGO_DEFER([&]() {
342	    // make producer quit
343	    mt_list_.done();
344	  });
345	
346	  VectorItem vector_item;
347	  while (mt_list_.consume(&vector_item)) {
348	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
349	      LOG_DEBUG("add_vec cancelled.");
350	      return;
351	    }
352	
353	    const void *vector = vector_item.vec_.data();
354	    std::string new_vector;
355	
356	
357	    if (need_convert) {
358	      IndexQueryMeta new_meta;
359	      if (target_streamer_reformer_->convert(vector, original_query_meta_,
360	                                             &new_vector, &new_meta) != 0) {
361	        LOG_ERROR("Failed to transform vector");
362	        *result = IndexError_Runtime;
363	        return;
364	      }
365	      vector = new_vector.data();
366	    }
367	    // 1. no reformer: target_streamer_query_meta_ = original_query_meta_
368	    // 2. has reformer, matched(need_convert = false): use
369	    // target_streamer_query_meta_
370	    // 3. has reformer, not matched(need_convert = true): use
371	    // target_streamer_query_meta_
372	
373	
374	    // TODO: use id instead of key
375	    int ret = target_streamer_->add_with_id_impl(
376	        (uint32_t)vector_item.pkey_, vector, target_streamer_query_meta,
377	        target_streamer_context);
378	    if (ret != 0) {
379	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
380	                ret, IndexError::What(ret), (size_t)vector_item.pkey_);
381	      *result = ret;
382	      return;
383	    }
384	  }
385	
386	  *result = 0;
387	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
388	  return;
389	}
