419	void MixedStreamerReducer::add_sparse_vec(int *result) {
420	  ailego::ElapsedTime timer;
421	  auto target_streamer_context = target_streamer_->create_context();
422	  auto target_streamer_query_meta = IndexQueryMeta{
423	      IndexMeta::MetaType::MT_SPARSE,
424	      target_streamer_->meta().data_type(),
425	  };
426	
427	  auto need_convert = !is_target_and_source_same_reformer_ &&
428	                      target_streamer_reformer_ != nullptr;
429	
430	  AILEGO_DEFER([&]() {
431	    // make producer quit
432	    sparse_mt_list_.done();
433	  });
434	
435	  SparseVectorItem sparse_vector_item;
436	  while (sparse_mt_list_.consume(&sparse_vector_item)) {
437	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
438	      LOG_DEBUG("add_sparse_vec cancelled.");
439	      return;
440	    }
441	    auto sparse_count = sparse_vector_item.sparse_indices_.size();
442	    auto indices = sparse_vector_item.sparse_indices_.data();
443	    auto values = sparse_vector_item.sparse_values_.data();
444	
445	    std::string converted_sparse_values_buffer;
446	    if (need_convert) {
447	      IndexQueryMeta new_meta;
448	      if (target_streamer_reformer_->convert(
449	              sparse_count, indices, values, original_query_meta_,
450	              &converted_sparse_values_buffer, &new_meta) != 0) {
451	        LOG_ERROR("Failed to transform vector");
452	        *result = IndexError_Runtime;
453	        return;
454	      }
455	      values = converted_sparse_values_buffer.data();
456	      target_streamer_query_meta = new_meta;
457	    }
458	
459	    // TODO: use id instead of key
460	    int ret = target_streamer_->add_with_id_impl(
461	        (uint32_t)sparse_vector_item.pkey_, sparse_count, indices, values,
462	        target_streamer_query_meta, target_streamer_context);
463	    if (ret != 0) {
464	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
465	                ret, IndexError::What(ret), (size_t)sparse_vector_item.pkey_);
466	      *result = ret;
467	      return;
468	    }
469	  }
470	
471	  *result = 0;
472	  LOG_DEBUG("add_sparse_vec. cost time: [%zu]s", (size_t)timer.seconds());
473	  return;
474	}
