542	void MixedStreamerReducer::PushToDocCache(const IndexQueryMeta &meta,
543	                                          uint32_t doc_id, std::string &doc) {
544	  std::lock_guard<std::mutex> lock(mutex_);
545	  while (doc_cache_.size() <= doc_id) {
546	    std::string fake_data(meta.dimension() * meta.unit_size(), 0);
547	    doc_cache_.push_back(std::make_pair(kInvalidKey, fake_data));
548	  }
549	  doc_cache_[doc_id] = std::make_pair(doc_id, doc);
550	}
