131	int MixedStreamerReducer::reduce(const IndexFilter &filter) {
132	  if (state_ != STATE_FEED) {
133	    LOG_ERROR("Feed streamers first");
134	    return IndexError_Uninitialized;
135	  }
136	  if (thread_pool_ == nullptr) {
137	    LOG_ERROR("Thread pool is not set");
138	    return IndexError_Uninitialized;
139	  }
140	
141	  ailego::ElapsedTime timer;
142	
143	
144	  std::vector<int> add_results(num_of_add_threads_, -1);
145	  auto add_group = thread_pool_->make_group();
146	
147	  std::vector<int> read_results(streamers_.size(), -1);
148	  // TODO: use id instead of key
149	  // When merging into a non-empty target (e.g. reusing one input as base),
150	  // append new docs after the existing ones instead of overwriting from 0.
151	  uint32_t id_offset = 0;
152	  uint32_t next_id = 0;
153	  if (target_builder_ == nullptr) {
154	    if (is_sparse_) {
155	      auto provider = target_streamer_->create_sparse_provider();
156	      if (provider) next_id = provider->count();
157	    } else {
158	      auto provider = target_streamer_->create_provider();
159	      if (provider) next_id = provider->count();
160	    }
161	  }
162	
163	  if (is_sparse_) {
164	    for (size_t i = 0; i < num_of_add_threads_; i++) {
165	      add_group->submit(ailego::Closure::New(
166	          this, &MixedStreamerReducer::add_sparse_vec, &add_results[i]));
167	    }
168	
169	    for (size_t i = 0; i < streamers_.size(); i++) {
170	      // due to filter, producing can't be parallel
171	      read_results[i] = read_sparse_vec(i, filter, id_offset, &next_id);
172	      id_offset += streamers_[i]->create_sparse_provider()->count();
173	    }
174	
175	    sparse_mt_list_.done();
176	  } else {
177	    for (size_t i = 0; i < num_of_add_threads_; i++) {
178	      add_group->submit(ailego::Closure::New(
179	          this, &MixedStreamerReducer::add_vec, &add_results[i]));
180	      // add_vec(&add_results[i]);
181	    }
182	
183	    for (size_t i = 0; i < streamers_.size(); i++) {
184	      auto provider = streamers_[i]->create_provider();
185	      if (!provider) {
186	        LOG_ERROR("Failed to create source provider, index=%zu", i);
187	        read_results[i] = IndexError_Runtime;
188	        break;
189	      }
190	      read_results[i] = read_vec(i, provider, filter, id_offset, &next_id);
191	      if (read_results[i] != 0) {
192	        break;
193	      }
194	      id_offset += provider->count();
195	    }
196	
197	    mt_list_.done();
198	  }
199	  add_group->wait_finish();
200	
201	  auto check_results = [](const std::vector<int> &results) -> bool {
202	    return std::all_of(std::begin(results), std::end(results),
203	                       [](int item) { return item == 0; });
204	  };
205	
206	  if (!check_results(read_results)) {
207	    LOG_ERROR("Get vector from entities failed");
208	    return IndexError_Runtime;
209	  }
210	
211	  if (!check_results(add_results)) {
212	    LOG_ERROR("add vector failed");
213	    return IndexError_Runtime;
214	  }
215	
216	  stats_.set_reduced_costtime(timer.seconds());
217	  state_ = STATE_REDUCE;
218	  if (target_builder_ != nullptr) {
219	    int ret = IndexBuild();
220	    if (ret != 0) {
221	      LOG_ERROR("Failed to build target index, ret=%d", ret);
222	      return ret;
223	    }
224	  }
225	
226	  LOG_INFO("End brute force reduce. cost time: [%zu]s",
227	           (size_t)timer.seconds());
228	  return 0;
229	}
