638	Status SegmentHelper::ReduceVectorIndex(
639	    const CollectionSchema::Ptr schema,
640	    const std::vector<Segment::Ptr> &input_segments,
641	    const std::string &output_segment_path, const IndexFilter::Ptr &filter,
642	    std::function<BlockID()> &block_id_generator, uint64_t min_doc_id,
643	    uint64_t max_doc_id, uint32_t doc_count, int concurrency,
644	    std::vector<BlockMeta> *output_block_metas) {
645	  Status s;
646	
647	  // vector
648	  auto vector_fields = schema->vector_fields();
649	  for (auto &field : vector_fields) {
650	    auto vector_index_params =
651	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
652	
653	    using FetchIndexersFn =
654	        std::vector<VectorColumnIndexer::Ptr> (Segment::*)(const std::string &)
655	            const;
656	    auto collect_merge_indexers = [&](FetchIndexersFn fetch) {
657	      std::vector<VectorColumnIndexer::Ptr> source_indexers;
658	      for (const auto &seg : input_segments) {
659	        auto seg_indexers = (seg.get()->*fetch)(field->name());
660	        source_indexers.insert(source_indexers.end(), seg_indexers.begin(),
661	                               seg_indexers.end());
662	      }
663	      return source_indexers;
664	    };
665	
666	    auto vector_block_id = block_id_generator();
667	    if (vector_index_params->quantize_type() == QuantizeType::UNDEFINED) {
668	      auto vector_index_path = FileHelper::MakeVectorIndexPath(
669	          output_segment_path, field->name(), vector_block_id);
670	
671	      s = MergeWithOptionalReuse(
672	          vector_index_path, *field,
673	          collect_merge_indexers(&Segment::get_vector_indexer), filter,
674	          concurrency, nullptr);
675	      CHECK_RETURN_STATUS(s);
676	
677	      BlockMeta new_block_meta;
678	      new_block_meta.set_id(vector_block_id);
679	      new_block_meta.set_type(BlockType::VECTOR_INDEX);
680	      new_block_meta.set_columns({field->name()});
681	      new_block_meta.set_min_doc_id(min_doc_id);
682	      new_block_meta.set_max_doc_id(max_doc_id);
683	      new_block_meta.set_doc_count(doc_count);
684	
685	      output_block_metas->push_back(new_block_meta);
686	    } else {
687	      auto vector_index_path = FileHelper::MakeVectorIndexPath(
688	          output_segment_path, field->name(), vector_block_id);
689	
690	      auto field_without_quantize = std::make_shared<FieldSchema>(*field);
691	      field_without_quantize->set_index_params(MakeDefaultVectorIndexParams(
692	          vector_index_params->metric_type(),
693	          vector_index_params->use_flat_contiguous_memory(),
694	          segment_detail::FlatStorageDataTypeForField(
695	              field->data_type(), vector_index_params->flat_data_type())));
696	
697	      VectorColumnIndexer::Ptr vector_indexer;
698	      s = MergeWithOptionalReuse(
699	          vector_index_path, *field_without_quantize,
700	          collect_merge_indexers(&Segment::get_vector_indexer), filter,
701	          concurrency, &vector_indexer);
702	      CHECK_RETURN_STATUS(s);
703	
704	      // HNSW_RABITQ training relies on the raw provider held by the flat
705	      // indexer, so its Close() is deferred until after the quantize indexer
706	      // is written.
707	      core::IndexProvider::Pointer raw_vector_provider;
708	      if (vector_index_params->type() == IndexType::HNSW_RABITQ) {
709	        raw_vector_provider = vector_indexer->create_index_provider();
710	      }
711	
712	      std::shared_ptr<FieldSchema> field_for_quantize;
713	      s = PrepareQuantizeField(*field, raw_vector_provider,
714	                               &field_for_quantize);
715	      CHECK_RETURN_STATUS(s);
716	
717	      BlockMeta new_block_meta;
718	      new_block_meta.set_id(vector_block_id);
719	      new_block_meta.set_type(BlockType::VECTOR_INDEX);
720	      new_block_meta.set_columns({field->name()});
721	      new_block_meta.set_min_doc_id(min_doc_id);
722	      new_block_meta.set_max_doc_id(max_doc_id);
723	      new_block_meta.set_doc_count(doc_count);
724	      output_block_metas->push_back(new_block_meta);
725	
726	      // create quantize index
727	      auto vector_quan_block_id = block_id_generator();
728	
729	      auto vector_quan_index_path = FileHelper::MakeQuantizeVectorIndexPath(
730	          output_segment_path, field->name(), vector_quan_block_id);
731	
732	      // RABITQ requires raw fp32 vectors as input, because re-encoding the
733	      // already-encoded quant indexers would produce garbage data. Other
734	      // types require the quantized vectors as input.
735	      auto quant_merge_sources =
736	          (vector_index_params->quantize_type() == QuantizeType::RABITQ)
737	              ? collect_merge_indexers(&Segment::get_vector_indexer)
738	              : collect_merge_indexers(&Segment::get_quant_vector_indexer);
739	
740	      s = MergeWithOptionalReuse(vector_quan_index_path, *field_for_quantize,
741	                                 quant_merge_sources, filter, concurrency,
742	                                 nullptr);
743	      CHECK_RETURN_STATUS(s);
744	
745	      s = vector_indexer->Close();
746	      CHECK_RETURN_STATUS(s);
747	
748	      new_block_meta.set_id(vector_quan_block_id);
749	      new_block_meta.set_type(BlockType::VECTOR_INDEX_QUANTIZE);
750	      new_block_meta.set_columns({field->name()});
751	      new_block_meta.set_min_doc_id(min_doc_id);
752	      new_block_meta.set_max_doc_id(max_doc_id);
753	      new_block_meta.set_doc_count(doc_count);
754	      output_block_metas->push_back(new_block_meta);
755	    }
756	  }
757	
758	  return Status::OK();
759	}
