763	// Only the first indexer's file is reused as the merge base; the remaining
764	// indexers are merged in via Merge(). Reuse is restricted to streaming
765	// indexes (HNSW, FLAT). Builder-rebuild indexes (IVF, VAMANA) and HNSW_RABITQ,
766	// IVF_RABITQ fall back to the full-rebuild merge.
767	bool CanReuseFirstIndexer(const std::vector<VectorColumnIndexer::Ptr> &indexers,
768	                          const FieldSchema &output_field,
769	                          const IndexFilter::Ptr &filter) {
770	  if (filter != nullptr || indexers.empty()) {
771	    return false;
772	  }
773	  if (output_field.index_type() != IndexType::HNSW &&
774	      output_field.index_type() != IndexType::FLAT) {
775	    return false;
776	  }
