Status SegmentImpl::Delete(uint64_t g_doc_id) {
  std::lock_guard lock(seg_mtx_);
  if (delete_store_->is_deleted(g_doc_id)) {
    return Status::NotFound("g_doc_id:", g_doc_id, " already deleted");
  }

  Doc mutable_doc;
  mutable_doc.set_doc_id(g_doc_id);
